return ['domain'=>'presspermit-pro19)) ? 0 : ((n % 10 >= 2 && n % 10 <= 9 && (n % 100 < 11 || n % 100 > 19)) ? 1 : 2);','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'lt_LT>= 2 && (n % 100 < 10 || n % 100 >= 20) ? 1: 2);','project-id-version'=>'PublishPress Permissions Pro 4.8.1','pot-creation-date'=>'2026-04-02T18:54:49+00:00','po-revision-date'=>'2026-10-01 19:50+0000','x-generator'=>'Weblate 2026.6.1','messages'=>['PublishPress Permissions Pro'=>'PublishPress Permissions Pro','https://publishpress.com/permissions'=>'https://publishpress.com/permissions','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress leidimai leidžia jums įgalinti arba atsisakyti prieigos prie įrašų, puslapių, kategorijų, žymų ir dar daugiau.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Should pages with privacy status "premium" require set_pages_premium and edit_premium_pages capabilities? If so, you can %1$sassign a status-specific Page Editor role%2$s or %3$sadd the capabilities directly to a role%4$s.'=>'Ar puslapiai su privatumo statusu "premium" turėtų reikalauti set_pages_premium ir edit_premium_pages teisių? Jei taip, galite %1$spriskirti statuso specifinę puslapio redaktoriaus rolę%2$s arba %3$spridėti teises tiesiogiai prie rolės%4$s.','Note: Workflow sequence and branching for pre-publication is configured %son a separate screen%s'=>'Pastaba: Darbo eigos seka ir šakos prieš publikavimą yra sukonfigūruota %son a separate screen%s','Additional settings provided by the %s module.'=>'Papildomi nustatymai, kuriuos teikia %s modulis.','Note: If you deactive, re-entry of the license key will be required for re-activation.'=>'Pastaba: Jei deaktivuosite, licencijos rakto pakartotinis įvedimas bus būtinas norint jį vėl aktyvuoti.','If enabled, custom group membership is applied network-wide (though role assignments are still site-specific).'=>'Jei įjungta, vartotojų grupių narystė taikoma visam tinklui (nors rolės priskyrimai vis dar yra specifiniai svetainei).','Can create network-wide permission groups'=>'Gali kurti tinklo mastu galiojusias leidimų grupes','If group editing is allowed, can also modify network group membership'=>'Jei leidžiama grupių redagavimas, taip pat gali keisti tinklo grupių narystę','This feature will control direct URL access to files in /uploads/ folder. By default, files are blocked if they are attached to a post which the user can\'t view.'=>'Ši funkcija kontroliuos tiesioginę URL prieigą prie failų /uploads/ kataloge. Pagal numatytuosius nustatymus, failai yra blokuojami, jei jie yra prijungti prie įrašo, kurio vartotojas negali peržiūrėti.','File Access on multisite installations will require the following rules to be inserted above the stock ms-files.php rules in the %1$smain .htaccess file%2$s:'=>'Failų prieiga multisaitų įrenginiuose reikalauja, kad šios taisyklės būtų įterptos virš standartinių ms-files.php taisyklių %1$smain .htaccess faile%2$s:','But your .htaccess is missing or not writeable!'=>'Bet jūsų .htaccess trūksta arba nėra rašoma!','.htaccess needs to be updated to include these rules.'=>'.htaccess turi būti atnaujintas, kad įtrauktų šias taisykles.','.htaccess file has all required rules.'=>'.htaccess failas turi visas reikalingas taisykles.','These rules will not be inserted automatically.  You are responsible for editing .htaccess and later removing the rules if the functionality is no longer desired.'=>'Šios taisyklės nebus įterptos automatiškai. Jūs esate atsakingi už .htaccess redagavimą ir vėliau taisyklių pašalinimą, jei funkcionalumas nebebus pageidaujamas.','Note that an additional rule will need to be added with each new site. %1$sTo eliminate this requirement, research "WordPress remove ms-files".%2$s'=>'Atkreipkite dėmesį, kad su kiekviena nauja svetaine reikės pridėti papildomą taisyklę. %1$sNorėdami pašalinti šį reikalavimą, tyrinėkite "WordPress remove ms-files".%2$s','You will need to manually restore the .htacces file to default contents if anything goes wrong. Proceed?'=>'Jei kas nors nepavyksta, jums reikės rankiniu būdu atkurti .htaccess failą į numatytąsias turinio. Ar tęsti?','Update .htaccess now'=>'Atnaujinti .htaccess dabar','only for sites with protected files'=>'tik apsaugotoms failų svetainėms','for all sites'=>'visoms svetainėms','NONE: remove Permissions rules'=>'NĖRA: pašalinti teisių taisykles','Since the plugin is not network-activated, you will need to modify the .htaccess file manually, inserting a RewriteRule as shown above for each site which needs file filtering.'=>'Kadangi pluginas nėra tinklo aktyvuotas, jums reikės rankiniu būdu modifikuoti .htaccess failą, įterpdami RewriteRule, kaip parodyta aukščiau, kiekvienai svetainei, kuriai reikia failų filtravimo.','This extends the File Access feature to files that are not attached to any post. This will not apply to user who have the edit_private_files or pp_list_all_files capability.'=>'Tai praplečia failų prieigos funkciją failams, kurie nėra prijungti prie jokio įrašo. Tai nebus taikoma vartotojams, turintiems edit_private_files arba pp_list_all_files teisę.','Make attached files unreadable to users who do not have the edit_private_files or pp_list_all_files capability.'=>'Padarykite prijungtus failus neskaitytus vartotojams, kurie neturi edit_private_files arba pp_list_all_files teisės.','Improve Media Library performance by disabling file filtering for thumbnails (size specified in Settings > Media).'=>'Pagerinkite Medijos bibliotekos našumą, išjungdami failų filtravimą miniatiūroms (dydis nurodytas Nustatymuose > Medija).','On some sites, an additional redirect is required to correctly deliver protected files. Leave this disabled for better performance if possible.'=>'Kai kuriose svetainėse reikalingas papildomas peradresavimas, kad būtų teisingai pateikti apsaugoti failai. Jei įmanoma, palikite tai išjungtą, kad pagerintumėte našumą.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys (at next site access) that protect the files.'=>'Failų prieigos funkcija naudoja %1$s.htaccess%2$s failą, esantį %3$suploads/.htaccess%4$s. Paprastai jokių veiksmų nereikia, tačiau spustelėjus žemiau esančią mygtuką, bus atnaujinti URL raktai (kitam svetainės prisijungimui), kurie apsaugo failus.','The File Access feature uses an %1$s.htaccess%2$s file located at %3$suploads/.htaccess%4$s. Normally no action is needed, but clicking the button below will update the URL keys that protect the files.'=>'Failų prieigos funkcija naudoja %1$s.htaccess%2$s failą, esantį %3$suploads/.htaccess%4$s. Paprastai jokių veiksmų nereikia, tačiau spustelėjus žemiau esančią mygtuką, bus atnaujinti URL raktai, kurie apsaugo failus.','Best practice is to access the above url periodically (using your own cron service) to prevent long-term bookmarking of protected files.'=>'Geriausia praktika yra periodiškai pasiekti aukščiau pateiktą URL (naudojant savo cron paslaugą), kad būtų išvengta ilgalaikio apsaugotų failų žymėjimo.','Supply a custom key which will enable a support url to regenerate file access keys.  Then execute the url regularly (using your own cron service) to prevent long-term bookmarking of protected files.'=>'Pateikite individualų raktą, kuris leis palaikymo URL regeneruoti failų prieigos raktus. Tada reguliariai vykdykite URL (naudodami savo cron paslaugą), kad būtų išvengta ilgalaikio apsaugotų failų žymėjimo.','File Access can also protect files uploaded by FTP or other manual file copy, but does not detect them automatically. Click the button below to scan your uploads folder for files to protect.'=>'Failų prieiga taip pat gali apsaugoti failus, įkeltus per FTP ar kitą rankinį failų kopijavimą, tačiau jų automatiškai neatpažįsta. Spustelėkite žemiau esantį mygtuką, kad nuskenuotumėte savo įkėlimo katalogą, kad surastumėte failus, kuriuos norite apsaugoti.','Invalid file filtering key argument.'=>'Neteisingas failų filtravimo rakto argumentas.','Please configure File Access options!'=>'Prašome sukonfigūruoti Failų Prieigos parinktis!','The wp-content folder cannot be relocated outside the main WordPress folder.'=>'wp-content aplanko negalima perkelti už pagrindinio WordPress aplanko.','Files linked in post content must be in %1$s (or a subfolder of it). If you move files, consider using a %2$s search and replace plugin%3$s to update those URLs.'=>'Failai, susieti su įrašų turiniu, turi būti %1$s (arba jo subkataloge). Jei perkelsite failus, apsvarstykite galimybę naudoti %2$s paieškos ir pakeitimo papildinį%3$s, kad atnaujintumėte tuos URL.','File Access can also protect files uploaded by FTP or other manual processes, but does not detect them automatically. This utility can find and protect any uploaded files.'=>'Failų prieiga taip pat gali apsaugoti FTP arba kitais rankiniais procesais įkeltus failus, tačiau automatiškai jų neatpažįsta. Ši priemonė gali rasti ir apsaugoti bet kuriuos įkeltus failus.','To run this utility by cron task or other direct request, use the following URL:'=>'Norėdami paleisti šią priemonę pagal cron užduotį arba kitą tiesioginį prašymą, naudokite šią URL:','To run this utility by direct URL, set a file filtering regen key on Permissions Settings'=>'Norėdami paleisti šią priemonę tiesioginiu URL, nustatykite failų filtravimo regeneravimo raktą teisių nustatymuose','Note: Direct access to uploaded file attachments cannot be filtered because your WP_CONTENT_DIR is not in the WordPress branch.'=>'Pastaba: Tiesioginio prieigos prie įkeltų failų priedų negalima filtruoti, nes jūsų WP_CONTENT_DIR nėra WordPress šaknyje.','The operation was terminated due to an invalid configuration.'=>'Veikla buvo nutraukta dėl neteisingos konfigūracijos.','Checking %s posts / pages...'=>'Tikrinama %s įrašų / puslapių...','%1$s skipping unfilterable file in %2$s "%3$s":%4$s %5$s'=>'%1$s praleidžia nefiltruojamą failą %2$s "%3$s":%4$s %5$s','%1$s skipping missing file in %2$s "%3$s":%4$s %5$s'=>'%1$s praleidžia trūkstamą failą %2$s "%3$s":%4$s %5$s','%1$sNew attachment in %2$s "%3$s":%4$s %5$s'=>'%1$sNaujas priedas %2$s "%3$s":%4$s %5$s','%s linked uploads were found in your post / page content.'=>'%s susiję įkeltieji failai buvo rasti jūsų įrašo / puslapio turinyje.','%s attachment records were added to the database.'=>'%s priedų įrašai buvo pridėti prie duomenų bazės.','All linked uploads are already registered as attachments.'=>'Visi susiję įkeltieji failai jau yra registruoti kaip priedai.','Statuses enabled here are available as Visibility options for post publishing. Affected posts become inaccessable without a corresponding status-specific role assignment.'=>'Čia įgalinti statusai yra prieinami kaip matomumo parinktys įrašų publikavimui. Paveikti įrašai tampa nepasiekiami be atitinkamo statuso specifinio vaidmens priskyrimo.','Statuses enabled here are available in the editor as additional steps between Draft and Published.'=>'Čia įgalinti statusai yra prieinami redaktoriuje kaip papildomi žingsniai tarp Juodraščio ir Publikuoto.','Statuses alter your content\'s accessibility by imposing additional capability requirements.'=>'Statusai keičia jūsų turinio prieinamumą, nustatydami papildomus pajėgumų reikalavimus.','Enable Custom Capabilities by toggling the link below status name. If enabled, non-Editors will need a corresponding %ssupplemental role%s to edit posts of that status.'=>'Įgalinkite pasirinktinius pajėgumus perjungdami nuorodą po statuso pavadinimu. Jei įjungta, ne-redaktoriai turės gauti atitinkamą %ssuplentinio vaidmens%s, kad galėtų redaguoti tų statusų įrašus.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button increment the post to the next workflow status permitted.'=>'Įrašo redagavimui vartotojo, kuris negali publikuoti, %sworkflow yra sukonfigūruotas%s, kad Publikuoti mygtukas padidintų įrašą iki kito leidžiamo workflow statuso.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button escalate the post to the highest-ordered workflow status permitted.'=>'Įrašo redagavimui vartotojo, kuris negali publikuoti, %sworkflow yra sukonfigūruotas%s, kad Publikuoti mygtukas padidintų įrašą iki aukščiausio leidžiamo workflow statuso.','For post edit by a user who cannot publish, the Publish button will escalate the post to the highest-order status permitted to the user.'=>'Įrašo redagavimui vartotojo, kuris negali publikuoti, Publikuoti mygtukas padidins įrašą iki aukščiausio statuso, leidžiamo vartotojui.','Please enable the PublishPress %sStatuses feature%s.'=>'Prašome įgalinti PublishPress %sStatusų funkciją%s.','Note that the Post Type itself will also need to have %sPermissions%s enabled.'=>'Atkreipkite dėmesį, kad pats Įrašo tipas taip pat turės turėti %sTeises%s įgalintas.','To disable custom visibility statuses, first re-assign posts to a different status.'=>'Norėdami išjungti pasirinktinius matomumo statusus, pirmiausia perpriskirkite įrašus kitam statusui.','Note, this only applies if the role definition includes the pp_moderate_any capability'=>'Pastaba, tai taikoma tik tuo atveju, jei vaidmens apibrėžimas apima pp_moderate_any pajėgumą','Create or edit custom Privacy or Workflow statuses.'=>'Sukurkite arba redaguokite pasirinktinius Privatumo arba Darbų eigų statusus.','Create or edit custom Privacy statuses.'=>'Sukurkite arba redaguokite pasirinktinius Privatumo statusus.','Extra Roles created as a type-specific copy of this role will enable assignment of specified custom statuses.'=>'Papildomi vaidmenys, sukurti kaip tipo specifinė šios rolės kopija, leis priskirti nurodytus pasirinktinius statusus.','Editors do not need status-specific editing capabilities for workflow posts (Assigned, In Progress, Approved).'=>'Redaktoriams nereikia statuso specifinių redagavimo pajėgumų workflow įrašams (Priskirta, Vykdoma, Patvirtinta).','If enabled, non-Editors will need to be granted editing access via the "Permissions" screen.'=>'Jei įjungta, ne-redaktoriams reikės suteikti redagavimo prieigą per "Teisių" ekraną.','If enabled, a Visibility Status dropdown will appear in Quick Edit for easy status assignment.'=>'Jei įjungta, greitojo redagavimo lange pasirodys matomumo statuso išskleidžiamasis sąrašas, kad būtų lengviau priskirti statusus.','If enabled, this will add Visibility Statuses support to the PublishPress Status plugin.'=>'Jei įjungta, tai pridės matomumo statusų palaikymą PublishPress Status papildiniui.','Post property or meta field to match with user field'=>'Įrašo ypatybė arba meta laukas, atitinkantis naudotojo lauką','User property or meta field to match with post field'=>'Naudotojo ypatybė arba meta laukas, atitinkantis įrašo lauką','User meta field to match with post field'=>'Naudotojo meta laukas, atitinkantis įrašo lauką','User role to include in synchronization'=>'Naudotojo rolė, kurią reikia įtraukti į sinchronizavimą','Parent id for created posts'=>'Tėvo id sukurtam įrašui','Choose post field from suggested meta key names'=>'Pasirinkite įrašo lauką iš pasiūlytų meta raktų pavadinimų','When a new user of specified role is added, create or designate a post for them.'=>'Kai pridedamas naujas vartotojas su nurodyta role, sukurkite arba priskirkite jam įrašą.','Create or designate a post for existing users.'=>'Sukurkite arba paskirkite įrašą esamiems naudotojams.','This post type is not hierarchical'=>'Šis įrašo tipas nėra hierarchinis','Automatically create a post for each user in selected roles.'=>'Automatiškai sukurkite įrašą kiekvienam naudotojui pasirinktuose rolėse.','Hint: If %s have custom fields (like email address), create one to assist field name discovery.'=>'Uždavinys: Jei %s turi pasirinktinius laukus (pavyzdžiui, el. pašto adresą), sukurkite vieną, kad padėtų atrasti lauko pavadinimus.','Enable each user to edit their own User Posts.'=>'Leiskite kiekvienam naudotojui redaguoti savo Naudotojo Įrašus.','Settings for replacing unreadable content with teaser text, provided by the %s module.'=>'Nustatymai, skirti pakeisti neskaitytiną turinį su anonsų tekstu, pateiktu %s modulyje.','Settings on this tab do not apply because teaser filtering is disabled for all post types.'=>'Nustatymai šioje kortelėje netaikomi, nes anonsų filtravimas yra išjungtas visiems įrašų tipams.','Since some browsers will cache feeds without regard to user login, block RSS content even for qualified users.'=>'Kadangi kai kurie naršyklės talpins šaltinius, nesirūpindamos vartotojo prisijungimu, blokuokite RSS turinį net kvalifikuotiems vartotojams.','This feature controls what users will see when trying to view content they are blocked from accessing.'=>'Ši funkcija kontroliuoja, ką vartotojai matys bandydami peržiūrėti turinį, prie kurio jie neturi prieigos.','These settings adjust which views, link types and visibility statuses the teaser is applied to.'=>'Šie nustatymai reguliuoja, kuriems rodiniams, nuorodų tipams ir matomumo statusams taikomas anonsas.','You can override Teaser settings within the Nav Menu by hiding links to unreadable posts that are associated with the terms you select below.'=>'Galite perrašyti anonsų nustatymus Naršymo meniu, paslėpdami nuorodas į neskaitytinas įrašas, susijusias su žemiau pasirinktais terminais.','Keep unreadable content hidden in the blogroll and link lists, but show the teaser on direct access attempts.'=>'Laikykite neskaitytiną turinį paslėptą blogroll\'e ir nuorodų sąrašuose, tačiau parodykite anonsą tiesioginio prieigos bandymų metu.','Hide unreadable private posts, but show a teaser for posts which are unreadable due to regular Privacy or Role Restrictions.'=>'Paslėpkite neskaitytinas privatų įrašus, tačiau parodykite anonsą tiems įrašams, kurie yra neskaitytini dėl įprastų privatumo ar rolės apribojimų.','If anyone tries to view a post they don\'t have access to, redirect to another post instead of displaying a teaser.'=>'Jei kas nors bando peržiūrėti įrašą, prie kurio jie neturi prieigos, nukreipkite į kitą įrašą, o ne rodykite anonsą.','Replace post content or excerpt with custom text, possibly including an inline login form. You can also add text before or after the post title and excerpt.'=>'Pakeiskite įrašo turinį arba ištrauką su pasirinktiniu tekstu, galbūt įtraukdami įterptą prisijungimo formą. Taip pat galite pridėti tekstą prieš arba po įrašo pavadinimo ir ištraukos.','Unreadable items of these comma-separated types will have nav menu item hidden.'=>'Neskaitytini šių kableliais atskirtų tipų elementai turės paslėptą naršymo meniu elementą.','Visibility Circle membership does not limit viewing access.'=>'Matomumo rato narystė neriboja peržiūros prieigos.','Editorial Circle membership does not limit editing access.'=>'Redakcinio rato narystė neriboja redagavimo prieigos.','When searching for users via Permissions ajax, return return only users registered to current site'=>'Ieškant vartotojų per teisių ajax, grąžinkite tik vartotojus, užsiregistravusius dabartinėje svetainėje','If user is a super admin or has \'pp_manage_network_members\' capability, user searches via Permissions ajax return users from all sites'=>'Jei vartotojas yra super administratorius arba turi \'pp_manage_network_members\' teisę, vartotojo paieška per teisių ajax grąžina vartotojus iš visų svetainių','Count users as a member of a BuddyPress Permissions Group only if they are a moderator of the BP group'=>'Skaičiuokite vartotojus kaip BuddyPress teisių grupės narius tik tuo atveju, jei jie yra BP grupės moderatorius','Count users as a member of a BuddyPress Permissions Group only if they are an administrator of the BP group'=>'Skaičiuokite vartotojus kaip BuddyPress teisių grupės narius tik tuo atveju, jei jie yra BP grupės administratorius','CMS Page Tree View plugin: hide \'add\' links (for all hierarchical post types) based on user\'s association permissions'=>'CMS puslapio medžio peržiūros papildinys: paslėpti \'pridėti\' nuorodas (visiems hierarchiniams įrašų tipams) pagal vartotojo asociacijos teises','CMS Page Tree View plugin: hide \'add\' links (for pages) based on user\'s page association permissions'=>'CMS puslapio medžio peržiūros papildinys: paslėpti \'pridėti\' nuorodas (puslapiams) pagal vartotojo puslapio asociacijos teises','CMS Page Tree View plugin: hide \'add\' links (for specified hierarchical post type) based on user\'s association permissions'=>'CMS puslapio medžio peržiūros papildinys: paslėpti \'pridėti\' nuorodas (nurodytam hierarchiniam įrašų tipui) pagal vartotojo asociacijos teises','Prevent Permission from filtering the Nested Pages listing at all'=>'Sustabdyti leidimą filtruoti įdėtus puslapius','Force Permissions to filter the Nested Pages listing'=>'Priversti leidimus filtruoti įdėtus puslapius','Comma-separated list of roles that are allowed to Quick Edit nested pages'=>'Kableliais atskirtas leidimų, kurie gali greitai redaguoti įdėtus puslapius, sąrašas','Comma-separated list of roles that are allowed to use the Context Menu'=>'Kableliais atskirtas leidimų, kurie gali naudoti kontekstinį meniu, sąrašas','Never allow unfiltered users to use the Context Menu, even if they have pp_force_quick_edit capability'=>'Niekuomet neleiskite nefiltruotiems vartotojams naudotis kontekstiniu meniu, net jei jie turi pp_force_quick_edit galimybę','Disable Add Child link unless user is unfiltered (Administrator or has pp_nested_pages_unfiltered capability)'=>'Išjunkite "Pridėti vaiką" nuorodą, nebent vartotojas būtų nefiltruotas (Administratorius arba turi pp_nested_pages_unfiltered galimybę)','Disable Add Child Page link unless user is unfiltered'=>'Išjungti "Pridėti vaikų puslapį" nuorodą, nebent vartotojas yra nefiltruotas','Disable Insert Page Before link unless user is unfiltered'=>'Išjungti "Įterpti puslapį prieš" nuorodą, nebent vartotojas yra nefiltruotas','Disable Insert Page After link unless user is unfiltered'=>'Išjungti "Įterpti puslapį po" nuorodą, nebent vartotojas yra nefiltruotas','Disable Push to Top link unless user is unfiltered'=>'Išjungti "Stumti į viršų" nuorodą, nebent vartotojas yra nefiltruotas','Disable Push to Bottom link unless user is unfiltered'=>'Išjungti "Stumti į apačią" nuorodą, nebent vartotojas yra nefiltruotas','Disable Clone link unless user is unfiltered'=>'Išjungti "Kopijuoti" nuorodą, nebent vartotojas yra nefiltruotas','License'=>'Licencija','License Key'=>'Licencijos raktas','Version'=>'Versija','settings'=>'nustatymai','Key Expired'=>'Raktas pasibaigė','Deactivate Key'=>'Deaktyvuoti raktą','Key Activated'=>'Raktas aktyvuotas','(please enter publishpress.com key)'=>'(prašome įvesti publishpress.com raktą)','Activate Key'=>'Aktyvuoti raktą','Note: Renewal does not require deactivation. If you do deactivate, re-entry of the license key will be required.'=>'Pastaba: Atkūrimas nereikalauja deaktyvavimo. Jei deaktyvuosite, reikės vėl įvesti licencijos raktą.','Your license key has expired. For continued priority support, %1$splease renew%2$s.'=>'Jūsų licencijos raktas pasibaigė. Norint gauti tolesnę prioriteto pagalbą, %1$sprašome atnaujinti%2$s.','Your license key will expire today. For updates and priority support, %1$splease renew%2$s.'=>'Jūsų licencijos raktas baigs galioti šiandien. Norint gauti atnaujinimus ir prioriteto pagalbą, %1$sprašome atnaujinti%2$s.','Your license key (for plugin updates) will expire in %1$d day(s). For updates and priority support, %2$splease renew%3$s.'=>'Jūsų licencijos raktas (plugin atnaujinimams) baigs galioti per %1$d dieną/dienų. Norint gauti atnaujinimus ir prioriteto pagalbą, %2$spraskome atnaujinti%3$s.','For updates to Permissions Pro, activate your %1$sPublishPress license key%2$s.'=>'Norint gauti atnaujinimus dėl Permissions Pro, aktyvuokite savo %1$sPublishPress licencijos rak